package tv.glass.launcher;

import static androidx.test.platform.app.InstrumentationRegistry.getInstrumentation;
import static org.junit.Assert.*;
import android.graphics.SurfaceTexture;
import android.os.SystemClock;
import android.view.Surface;
import androidx.test.ext.junit.runners.AndroidJUnit4;
import io.github.jqssun.airplay.renderer.VideoRenderer;
import java.lang.reflect.Field;
import java.util.Base64;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.Test;
import org.junit.runner.RunWith;

/** Real AVC decoding and session cancellation, on an emulator only.
 * Fixtures are single black frames generated by:
 * ffmpeg -f lavfi -i color=c=black:s=336x720:r=30 -frames:v 1
 *   -c:v libx264 -profile:v baseline -tune zerolatency -f h264 out.h264
 * Repeat at 332x720; normalize Annex-B start codes to four bytes (as UxPlay does).
 * These do not establish TCL hardware behavior or sender/network timing. */
@RunWith(AndroidJUnit4.class)
public class AirPlayRecoveryTest {
    private static Object field(Object target,String name)throws Exception {
        Field f=target.getClass().getDeclaredField(name);f.setAccessible(true);return f.get(target);
    }
    private static long outputs(VideoRenderer r)throws Exception { return (Long)field(r,"_outFrames"); }
    private static void awaitOutput(VideoRenderer r,long before)throws Exception {
        long until=SystemClock.elapsedRealtime()+5000;
        while(SystemClock.elapsedRealtime()<until) {
            // Use the renderer lock: codec callbacks publish these counters under it.
            synchronized(field(r,"lock")) { if(outputs(r)>before)return; }
            SystemClock.sleep(20);
        }
        fail("No decoded output after resolution/session change");
    }
    @Test public void decodesAcrossCropChangesAndRepeatedSessions()throws Exception {
        VideoRenderer r=new VideoRenderer(getInstrumentation().getTargetContext());
        SurfaceTexture texture=new SurfaceTexture(false);
        Surface surface=new Surface(texture);
        try {
            r.setScheduledOutputBufferRelease(false);
            r.selectDecoders(720,1280,30,false);
            r.setSurface(surface);
            for(int session=0;session<3;session++) {
                r.startSession();
                for(int w:new int[]{336,332,336}) {
                    r.setResolution(w,720);
                    long before=outputs(r);
                    byte[] data=Base64.getDecoder().decode(w==336?FRAME336:FRAME332);
                    r.feedFrame(data,System.nanoTime(),false);
                    awaitOutput(r,before);
                }
                r.stopSession();
                assertNull("decoder released at session end",field(r,"codec"));
            }
        } finally { r.release();surface.release();texture.release(); }
    }
    @Test public void stoppedSessionCannotStartDecoderAfterSurfaceWait()throws Exception {
        VideoRenderer r=new VideoRenderer(getInstrumentation().getTargetContext());
        AtomicReference<Throwable> error=new AtomicReference<>();
        try {
            r.setResolution(336,720);r.startSession();
            Thread receiver=new Thread(()->{
                try { r.feedFrame(Base64.getDecoder().decode(FRAME336),System.nanoTime(),false); }
                catch(Throwable t) { error.set(t); }
            },"mirror-cancel-test");
            receiver.start();
            long until=SystemClock.elapsedRealtime()+1000;
            while(receiver.getState()!=Thread.State.TIMED_WAITING&&SystemClock.elapsedRealtime()<until)
                SystemClock.sleep(1);
            assertEquals("receiver entered first-frame surface wait",Thread.State.TIMED_WAITING,receiver.getState());
            r.stopSession();receiver.join(1500);
            assertFalse("stopped receive work finished",receiver.isAlive());
            assertNull(error.get());
            assertNull("no late decoder",field(r,"codec"));
            assertNull("no late GL pipeline",field(field(r,"pipeline"),"thread"));
        } finally { r.release(); }
    }
    private static final String FRAME336="";
    private static final String FRAME332="";
}
